import{_ as l}from"./chunks/comfyui_2026-07-13_093918_022.CsEPa01x.js";import{_ as t,o as a,c as i,at as r}from"./chunks/framework.CY22Hent.js";const s="/assets/comfyui_2026-07-11_020339_737.DTA9oxxb.png",e="/assets/comfyui_2026-07-27_105847_458.DcSWseWV.png",n="/assets/comfyui_2026-07-11_021033_929.B2mSlIhh.png",p="/assets/comfyui_2026-08-03_222132_151.Ci5ppRAY.png",m="/assets/comfyui_2026-08-03_222551_875.FW9QLMeh.png",c="/assets/comfyui_2026-08-03_223344_853.atcwip2Y.png",g="/assets/comfyui_2026-08-03_223602_630.DSVxABei.png",f="/assets/comfyui_2026-08-03_224128_664.Cn6dpgNn.png",d="/assets/comfyui_2026-07-13_103753_315.alogBA-7.png",y="/assets/comfyui_202607131057.CE17YckI.gif",u="/assets/comfyui_2026-07-13_112809_130.COS06lrn.png",_="/assets/comfyui_2026-07-13_113231_218.BSmFxyfH.png",h="/assets/comfyui_2026-07-29_161208_085.ByVT_UI5.png",C="/assets/comfyui_2026-07-29_162547_393.C-QX_Huu.png",I="/assets/comfyui_2026-07-29_162800_209.DVKUc8Lo.png",b="/assets/comfyui_2026-07-31_114039_334.BNIJa4PD.png",U="/assets/comfyui_2026-08-03_214441_836.DfmiWdbX.png",q="/assets/comfyui_2026-07-31_120442_284.Cor6G9DX.png",k="/assets/comfyui_2026-07-13_151107_094.DqS82eVG.png",V=JSON.parse('{"title":"ComfyUI笔记","description":"","frontmatter":{"title":"ComfyUI笔记","date":"2026-07-05T00:00:00.000Z","lastUpdated":"2026-08-04T00:00:00.000Z","categories":["AI"],"tags":["ComfyUI","AI"]},"headers":[],"relativePath":"blogs/ComfyUI/ComfyUI笔记.md","filePath":"blogs/ComfyUI/ComfyUI笔记.md"}'),x={name:"blogs/ComfyUI/ComfyUI笔记.md"};function P(A,o,N,S,D,z){return a(),i("div",null,[...o[0]||(o[0]=[r('<p>[toc]</p><h1 id="comfyui笔记" tabindex="-1">ComfyUI笔记 <a class="header-anchor" href="#comfyui笔记" aria-label="Permalink to &quot;ComfyUI笔记&quot;">​</a></h1><h2 id="comfyui-介绍" tabindex="-1">ComfyUI 介绍 <a class="header-anchor" href="#comfyui-介绍" aria-label="Permalink to &quot;ComfyUI 介绍&quot;">​</a></h2><p><a href="https://comfy.org/" target="_blank" rel="noreferrer">ComfyUI官网 https://comfy.org/</a></p><p><a href="https://comfy.org/zh-CN/" target="_blank" rel="noreferrer">ComfyUI 中文官网 https://comfy.org/zh-CN/</a></p><p><img src="'+l+'" alt="comfyui_2026-07-13_093918_022.png" loading="lazy"></p><p>ComfyUI是一款基于节点流程的AI图像生成工具，专为图像生成,视频生成,动画生成等任务设计，支持Windows、macOS、Linux多平台运行。</p><p>ComfyUI 是一个基于节点的、可扩展的 Stable Diffusion 图形界面工具。它允许用户通过连接不同的节点来构建复杂的图像生成工作流，从而无需编写代码。</p><blockquote><p>ComfyUI 核心功能和特点</p></blockquote><ol><li><strong>节点化工作流</strong>：通过拖拽节点并连接它们来创建图像生成流程，直观且灵活</li><li><strong>高度可扩展</strong>：支持大量自定义节点和扩展插件，社区活跃</li><li><strong>高清修复</strong>：内置高清修复功能，可生成更高分辨率的图像</li><li><strong>模型管理</strong>：支持多种模型格式，方便管理和切换不同的生成模型</li><li><strong>开源免费</strong>：完全开源，免费使用，拥有庞大的社区支持</li></ol><blockquote><p>ComfyUI 的使用场景</p></blockquote><ol><li><strong>AI 图像生成</strong>：使用 Stable Diffusion 模型生成各种风格的图像</li><li><strong>AI 视频生成</strong>：使用 Stable Diffusion 模型生成各种风格的视频</li><li><strong>图像编辑与修复</strong>：对现有图像进行修改、修复和增强</li><li><strong>创意设计</strong>：设计师可以使用 ComfyUI 创建概念艺术、插画、海报等</li><li><strong>批量生成</strong>：通过自定义工作流实现批量图像生成</li></ol><p><span style="color:red;">简而言之，ComfyUI 是一个强大的 AI 图像生成工具，通过节点化的方式让用户能够灵活地构建和控制图像生成流程，适合从入门到专业的各种用户。</span></p><h2 id="comfyui-安装" tabindex="-1">ComfyUI 安装 <a class="header-anchor" href="#comfyui-安装" aria-label="Permalink to &quot;ComfyUI 安装&quot;">​</a></h2><h3 id="comfyui-desktop-安装" tabindex="-1">ComfyUI Desktop 安装 <a class="header-anchor" href="#comfyui-desktop-安装" aria-label="Permalink to &quot;ComfyUI Desktop 安装&quot;">​</a></h3><p><img src="'+l+'" alt="comfyui_2026-07-13_093918_022.png" loading="lazy"></p><p>ComfyUI Desktop 是一个ComfyUI官方 推出的基于 Windows 的桌面应用，用户可以在 Windows 系统上直接运行 ComfyUI。</p><blockquote><p>配置需求</p></blockquote><p>强烈建议本地显卡是NVIDIA显卡。并且显卡显存在8GB以上。</p><blockquote><p>安装步骤</p></blockquote><ol><li>下载ComfyUI Desktop 安装包</li><li>双击运行安装包，按照提示安装。</li><li>安装完成后，会自动打开 ComfyUI Desktop。</li></ol><p>ComfyUI Desktop 安装后，会在安装目录下新建三个目录。我是安装在D盘。如图所示。 <img src="'+s+'" alt="comfyui_2026-07-11_020339_737.png" loading="lazy"></p><ul><li>ComfyUI-Cache目录:缓存目录，用于存储临时文件和缓存数据。空间不足时可以清空，不影响模型和软件本体。</li><li>ComfyUI-Installs目录:项目工程目录,用来隔离各个工程之间的文件，避免不同工程之间的文件冲突。例如，你可以创建一个名为&quot;项目1&quot;的工程，专门用于存放项目1的文件。 <ul><li>注意：每个工程的文件都是独立的，互不干扰。</li><li>注意：每个工程中可以创建多个工作流。一个工程就类似一个项目。</li></ul></li><li>ComfyUI-Shared目录:共享目录，用于存储需要共享的文件。包括各个模型文件等。</li></ul><p><span style="color:red;">注意：你下载的模型文件，就需要放在ComfyUI-Shared目录下。所有工作流共用的模型文件全部存在这里，ComfyUI 会自动检测并加载共享目录下的模型文件。</span></p><blockquote><p>模型目录</p></blockquote><p>在ComfyUI-Shared目录中的models目录下，可以看到代表各个模型类型的目录。不同的模型文件分别存在对应类型的目录下。</p><p><img src="'+e+'" alt="comfyui_2026-07-27_105847_458.png" loading="lazy"></p><blockquote><p>修改共享目录路径</p></blockquote><p>你也可以在ComfyUI Desktop 的设置中修改共享目录路径。如图所示。 <img src="'+n+'" alt="comfyui_2026-07-11_021033_929.png" loading="lazy"></p><h2 id="comfyui-基本概念" tabindex="-1">ComfyUI 基本概念 <a class="header-anchor" href="#comfyui-基本概念" aria-label="Permalink to &quot;ComfyUI 基本概念&quot;">​</a></h2><h3 id="实例" tabindex="-1">实例 <a class="header-anchor" href="#实例" aria-label="Permalink to &quot;实例&quot;">​</a></h3><p>如图所示，当一打开ComfyUI Desktop 时，首页出现的就是comfyui的仪表盘界面。 <img src="'+p+'" alt="comfyui_2026-08-03_222132_151.png" loading="lazy"></p><p>实例就是一个项目，也是一套独立完整的 ComfyUI 环境（独立文件夹）。当我们新建一个实例的时候，会在&quot;ComfyUI-Installs&quot;目录下新建一个文件夹，用来存放该实例的所有文件。</p><p>如图所示，一个实例相当于一个独立的项目工程。环境也是独立的，互不干扰。 <img src="'+m+'" alt="comfyui_2026-08-03_222551_875.png" loading="lazy"></p><p>如图所示，某个实例中的standalone-env目录就是该实例的Python环境。 <img src="'+c+'" alt="comfyui_2026-08-03_223344_853.png" loading="lazy"></p><p>如图所示，实例中的“ComfyUI/XXX”目录下就存放着属于该实例的模型目录，自定义节点包目录等。 <img src="'+g+'" alt="comfyui_2026-08-03_223602_630.png" loading="lazy"></p><p>如图所示，实例中的工作流的存储路径。工作流以json文件格式存储。 <img src="'+f+'" alt="comfyui_2026-08-03_224128_664.png" loading="lazy"></p><span style="color:red;"><p>注意事项：</p><p>① 每个实例中Python环境是隔离的。你在实例A中安装的Python依赖，不会应用到实例B。</p><p>② 每个实例中自定义节点也是隔离的。你可以在实例A中安装自定义节点，不会应用到实例B。同样，你可以在实例B中安装自定义节点，不会应用到实例A。</p><p>③ 实例中的模型也是隔离的，不过你也可以将模型文件下载到“ComfyUI-Shared/models”目录下。这个目录下的模型是所有实例共用的。</p><p>④ 实例中的工作流也是隔离的。你可以在实例A中创建工作流，不会影响到实例B。同样，你可以在实例B中创建工作流，不会影响到实例A。</p></span><h3 id="工作流-节点图" tabindex="-1">工作流（节点图） <a class="header-anchor" href="#工作流-节点图" aria-label="Permalink to &quot;工作流（节点图）&quot;">​</a></h3><p>ComfyUI 本身是一个用于构建 工作流 的桌面端工具。在这个工具中，工作流被定义为一组称为 节点 的程序对象，它们相互连接，形成一个网络。这个网络也被称为图。</p><p>即工作流就是节点与节点之间构建的图。即节点图。</p><p>ComfyUI 的工作流可以生成任何类型的媒体：图像、视频、音频、模型等。</p><h4 id="工作流包含的步骤" tabindex="-1">工作流包含的步骤 <a class="header-anchor" href="#工作流包含的步骤" aria-label="Permalink to &quot;工作流包含的步骤&quot;">​</a></h4><p>一个典型的工作流包含以下步骤：</p><ol><li>加载模型和 VAE</li><li>输入提示词</li><li>配置采样参数</li><li>生成图像</li><li>保存或后处理图像</li></ol><h4 id="工作流依赖文件" tabindex="-1">工作流依赖文件 <a class="header-anchor" href="#工作流依赖文件" aria-label="Permalink to &quot;工作流依赖文件&quot;">​</a></h4><p>我们经常可以从社区里获取到各种各样的工作流文件，但往往在运行之后发现工作流无法直接运行。</p><p>这是因为一个工作流文件除了工作流自身之外还要依赖于其它文件，比如媒体资产的输入、模型、自定义节点、相关的 Python 依赖等等。</p><p><span style="color:red;">ComfyUI 的工作流只有在所有相关依赖条件都被满足的情况下才能正常运行。</span></p><p>ComfyUI 工作流的依赖文件主要分为以下几类：</p><ul><li><strong>资产</strong>：包括音频、视频、图像等素材文件。</li><li><strong>模型</strong>：包括 Stable Diffusion 模型、VAE、ControlNet 等模型文件。</li><li><strong>自定义节点</strong>：包括自定义的节点、插件、插件等。</li><li><strong>Python 依赖</strong>：包括各种各样的 Python 库等。</li></ul><h4 id="工作流模板" tabindex="-1">工作流模板 <a class="header-anchor" href="#工作流模板" aria-label="Permalink to &quot;工作流模板&quot;">​</a></h4><p>工作流模板是 ComfyUI 中原生支持的模型工作流及自定义节点提供的模型工作流的模板文件。</p><blockquote><p>如何打开ComfyUI的工作流模板</p></blockquote><p>在侧边栏点击 Templates 图标即可打开工作流模板。你也可以通过菜单 工作流 → 浏览工作流模板 打开。</p><blockquote><p>如何使用工作流模板</p></blockquote><ol><li>加载模板： 点击你需要使用的任意模板以加载对应的模板工作流</li><li>下载模型： 在加载模板时，ComfyUI 会自动检查模型文件是否存在，如果模型文件不完整，则会提示你下载模型</li><li>使用工作流： 确定工作流的需要的各种要素如模型、输入图片、提示词等是完整的，然后点击运行按钮就可以开始使用工作流</li></ol><h3 id="节点-node" tabindex="-1">节点（Node） <a class="header-anchor" href="#节点-node" aria-label="Permalink to &quot;节点（Node）&quot;">​</a></h3><p>ComfyUI 是一个基于节点的图像生成工具，通过拖拽节点并连接它们来构建复杂的图像生成工作流。</p><p>节点是 ComfyUI 工作流的基本组成单元。每个节点都相当于一个独立的模块，有着自己独特的功能。</p><p>节点之间通过连线传递数据，我们可以像搭乐高积木一样搭建起来复杂的功能。最终形成一个网络，即工作流（节点图）。</p><blockquote><p>节点的基本概念</p></blockquote><ul><li><strong>节点</strong>：工作流的基本组成单元，每种节点都有各自特定的功能</li><li><strong>输入</strong>：节点接收的数据，通常是前一个节点的输出</li><li><strong>输出</strong>：节点处理后产生的数据，传递给下一个节点</li><li><strong>连接</strong>：节点之间通过连线传递数据，形成完整的工作流</li></ul><h4 id="常见的节点类型" tabindex="-1">常见的节点类型 <a class="header-anchor" href="#常见的节点类型" aria-label="Permalink to &quot;常见的节点类型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>分类</th><th>功能</th><th>常见节点</th></tr></thead><tbody><tr><td><strong>模型加载</strong></td><td>加载各种模型</td><td>Checkpoint Loader、CLIP Loader、UNet Loader、VAE Loader、LoRA Loader</td></tr><tr><td><strong>文本处理</strong></td><td>处理提示词</td><td>CLIP Text Encode</td></tr><tr><td><strong>图像生成</strong></td><td>生成图像</td><td>KSampler、Empty Latent Image</td></tr><tr><td><strong>图像处理</strong></td><td>处理图像</td><td>VAE Encode、VAE Decode、Load Image、Preview Image</td></tr><tr><td><strong>控制网络</strong></td><td>控制生成过程</td><td>ControlNet Loader、ControlNet Apply</td></tr></tbody></table><h4 id="节点如何运作" tabindex="-1">节点如何运作 <a class="header-anchor" href="#节点如何运作" aria-label="Permalink to &quot;节点如何运作&quot;">​</a></h4><p>在 ComfyUI 中，节点通过对数据进行处理以完成某种功能。</p><p>ComfyUI 节点几乎总至少有一个输入或输出，多数情况下同时具有多个输入与输出。</p><ul><li>输入端口：节点接收外部数据的端口。</li><li>输出端口：节点将处理后的数据发送到其他节点的端口。</li></ul><h4 id="节点状态" tabindex="-1">节点状态 <a class="header-anchor" href="#节点状态" aria-label="Permalink to &quot;节点状态&quot;">​</a></h4><p><img src="'+d+'" alt="comfyui_2026-07-13_103753_315.png" loading="lazy"></p><p>在 ComfyUI 中，节点有多种状态，下面是一些常见的节点状态：</p><ul><li><strong>正常(Normal)状态</strong>： 正常状态</li><li><strong>运行(Running)状态</strong>： 运行中状态，通常在你开始运行工作流后，正在执行的节点会显示这个状态</li><li><strong>错误(Error)状态</strong>： 节点错误，如果对应的节点输入存在问题，会导致了节点会显示这个状态，并用红色标识对应出错的输入节点，你需要解决对应出错的输入来保证工作流正常运行</li><li><strong>丢失(Missing)状态</strong>： 这个状态通常在你导入了一些工作流后会出现，存在两种可能： <ul><li>ComfyCore 原生节点丢失： 通常是因为 ComfyUI 的版本更新了，而你当前使用的 ComfyUI 版本较旧，你需要更新 ComfyUI 来解决这个问题</li><li>自定义节点丢失： 工作流中你使用了第三方作者开发的自定义节点，而本地ComfyUI环境中尚未安装对应扩展。</li></ul></li></ul><h4 id="节点之间的连接和取消连接" tabindex="-1">节点之间的连接和取消连接 <a class="header-anchor" href="#节点之间的连接和取消连接" aria-label="Permalink to &quot;节点之间的连接和取消连接&quot;">​</a></h4><p>在 ComfyUI 中，节点通过连线连接，从而让数据类型在不同的节点之间进行流转处理。</p><p><img src="'+y+'" alt="comfyui_202607131057.gif" loading="lazy"></p><ul><li><strong>连接</strong>： 在上一个节点的输出点中拖拽到下一个节点相同颜色的输入中，即可连接。</li><li><strong>取消连接</strong>： 在被输入的端点，点击后鼠标左键拖拽输入，即可取消连接，或者通过连线的中点菜单来取消连接。</li></ul><h4 id="节点外观" tabindex="-1">节点外观 <a class="header-anchor" href="#节点外观" aria-label="Permalink to &quot;节点外观&quot;">​</a></h4><p><img src="'+u+'" alt="comfyui_2026-07-13_112809_130.png" loading="lazy"></p><ul><li>标题：节点的名称，用于标识节点的功能。</li><li>输入端口：节点接收外部数据的端口。</li><li>输出端口：节点将处理后的数据发送到其他节点的端口。</li><li>组件：节点的功能组件，用于配置节点的行为。</li></ul><h4 id="节点上下文菜单" tabindex="-1">节点上下文菜单 <a class="header-anchor" href="#节点上下文菜单" aria-label="Permalink to &quot;节点上下文菜单&quot;">​</a></h4><p>通过在节点上点击鼠标右键，你可以展开对应的节点上下文菜单，例如下面是某个节点的上下文菜单截图。</p><p><img src="'+_+'" alt="comfyui_2026-07-13_113231_218.png" loading="lazy"></p><p>在节点的右键上下文菜单中你可以</p><ul><li><strong>调整节点的颜色样式</strong></li><li><strong>修改标题</strong></li><li><strong>克隆、复制、删除节点</strong></li><li><strong>....</strong></li></ul><h3 id="自定义节点-第三方节点" tabindex="-1">自定义节点（第三方节点） <a class="header-anchor" href="#自定义节点-第三方节点" aria-label="Permalink to &quot;自定义节点（第三方节点）&quot;">​</a></h3><p>当你在安装了 ComfyUI 后，你将会发现 ComfyUI 中已经包含了许多节点，这些原生的节点称为 Comfy Core 节点，这些节点都是由 ComfyUI 官方维护的。</p><p>此外还有许多来自 ComfyUI 社区的众多作者带来的各种各样的 <strong>自定义节点</strong>，这些<strong>自定义节点</strong>为 ComfyUI 带来了诸多的扩展功能，大大扩展了 ComfyUI 的功能和能力边界。</p><h4 id="什么是自定义节点包-第三方节点" tabindex="-1">什么是自定义节点包（第三方节点）？ <a class="header-anchor" href="#什么是自定义节点包-第三方节点" aria-label="Permalink to &quot;什么是自定义节点包（第三方节点）？&quot;">​</a></h4><p>自定义节点是第三方作者开发的节点，用于扩展 ComfyUI 功能。当comfyui的官方节点无法满足你的需求时，你可以考虑安装自定义节点。</p><p>如图所示，你可以在ComfyUI Desktop中，点击管理附属扩展按钮,打开自定义节点管理器。然后再其中搜索并安装自定义节点。 <img src="'+h+'" alt="comfyui_2026-07-29_161208_085.png" loading="lazy"></p><p><span style="color:red;">这个自定义节点管理器，其实就是comfyui-manager。</span></p><h4 id="使用自定义节点-第三方节点" tabindex="-1">使用自定义节点（第三方节点） <a class="header-anchor" href="#使用自定义节点-第三方节点" aria-label="Permalink to &quot;使用自定义节点（第三方节点）&quot;">​</a></h4><p><span style="color:red;">注意：详细的使用方法，还是需要看这些作者的文档。</span></p><p>例如当你安装了某一个自定义节点包后。如图所示，安装了KJNodes节点包。</p><p><img src="'+C+'" alt="comfyui_2026-07-29_162547_393.png" loading="lazy"></p><p>你可以通过两个方法找到安装的自定义节点。如图所示。</p><ul><li><strong>方法1</strong>：在左边侧边栏的节点菜单中找到自定义节点。</li><li><strong>方法2</strong>：在主界面点击右键，然后点击添加节点，即可找到自定义节点。</li><li><strong>方法3</strong>：在主界面双击左键，打开节点搜索框，然后从中找到自定义节点。</li></ul><p><img src="'+I+'" alt="comfyui_2026-07-29_162800_209.png" loading="lazy"><img src="'+b+'" alt="comfyui_2026-07-31_114039_334.png" loading="lazy"></p><p>之后将自定义节点拖拽到工作流中，即可使用。</p><h4 id="推荐的自定义节点包-第三方节点包" tabindex="-1">推荐的自定义节点包（第三方节点包） <a class="header-anchor" href="#推荐的自定义节点包-第三方节点包" aria-label="Permalink to &quot;推荐的自定义节点包（第三方节点包）&quot;">​</a></h4><blockquote><p><strong>ComfyUI controlnet aux 预处理器节点包</strong>（使用ControlNet必备）</p></blockquote><p><strong>comfyui_controlnet_aux</strong> 是 ComfyUI 生态中最主流、功能最全的第三方 ControlNet 预处理器节点包，由社区开发者 <code>Fannovel16</code> 维护，是绝大多数 ControlNet 工作流的标配组件。</p><p>核心优势：</p><ol><li>全类型覆盖：集成了几乎所有主流 ControlNet 对应的预处理器</li><li>多架构兼容：同时适配主流模型架构，参数内置对应优化。</li><li>xinsir 专属适配优化：针对 xinsir 系列模型做了专属坐标适配（scale_stick 开关），是使用 xinsir 模型的官方推荐配套节点。</li></ol><p>节点包中核心的检测模型、预处理逻辑，核心代码均移植自开发者 <code>lllyasviel</code> 开发的 ControlNet 官方项目中的 annotator 目录，开发者<code>lllyasviel</code> 也是 ControlNet 技术本身的发明者。</p><p><a href="https://github.com/lllyasviel/ControlNet" target="_blank" rel="noreferrer">ControlNet 官方项目地址： https://github.com/lllyasviel/ControlNet</a></p><p><a href="https://github.com/lllyasviel/ControlNet" target="_blank" rel="noreferrer">comfyui_controlnet_aux 预处理器节点包项目地址： https://github.com/lllyasviel/ControlNet</a></p><blockquote><p><strong>Efficiency Nodes</strong>（效率整合懒人节点，可选，建议安装）</p></blockquote><p>由作者：jags111开发，适用：零基础新手搭建简洁工作流、日常快速出图。</p><p>核心特色功能：</p><ol><li>把原生 7~9 个零散节点合并成单个大节点，不用一根根拉线，刚入门第一天就能跑出图，极大降低学习门槛。</li><li>内置快捷工具：分辨率预设、LoRA 一键开关、种子随机切换、CFG 步数快捷调节，不用反复拖拽原生节点。</li><li>完美兼容 SDXL、Qwen-Image、Z-Image-Turbo、Flux、Wan 所有新一代架构模型；</li><li>分组折叠、参数预设保存，新手搭建工作流效率提升一倍。</li></ol><p><span style="color:red;">入门启蒙神器，所有新手第一个安装的实用节点包。</span></p><blockquote><p><strong>ComfyUI-Custom-Scripts</strong>（界面交互增强脚本,使用embedding必备,建议安装）</p></blockquote><p>作者：pythongosssss。本质上不属于节点包，是浏览器前端增强脚本。用于提升ComfyUI的界面交互体验（自动排版节点、大图预览、历史记录、快捷键）。</p><p>核心特色功能：</p><ol><li>一键自动排布杂乱节点、对齐所有连线，拯救乱糟糟画布；</li><li>大图预览面板、历史生成图片记录回看、提示词收藏夹；</li><li>快捷键自定义、节点批量复制参数、画布缩放优化；</li><li>批量导出工作流、参数备份，拖拽作画顺滑度大幅提升。</li></ol><p><span style="color:red;">必装辅助工具，不分新手老手，永久常驻。</span></p><p>当安装了<strong>ComfyUI-Custom-Scripts</strong>之后，可以从设置之中找到该节点包的相关配置。 <img src="'+U+'" alt="comfyui_2026-08-03_214441_836.png" loading="lazy"></p><blockquote><p><strong>ComfyUI-Impact-Pack</strong>（人像修图天花板，工作室标配）</p></blockquote><p>作者：ltdrdata。该节点包适合于，能搭建基础工作流之后，想要解决 AI 通病：脸崩、手畸形、画面模糊等。</p><p>核心特色功能：</p><ol><li>FaceDetailer 人脸 / 手部自动修复（最高频）：自动修正扭曲五官、畸形手指，人像写真刚需；</li><li>SAM 图像分割、局部重绘、分区细节增强；</li></ol><p><span style="color:red;">静态绘画创作者第二常用插件。</span></p><blockquote><p><strong>KJNodes</strong>（全能进阶效率工具箱 + 新一代大模型专属优化套件）</p></blockquote><p>作者：kijai。<span style="color:red;">该节点包适合于需要跑 Wan 文生视频、搭建超大复杂工作流、多参数统一调控、12G 小显存跑 Qwen/Flux 大模型的进阶用户。</span></p><p>核心特色功能：</p><ol><li>Set/Get 全局变量（复杂分层工作流才用得上，新手简单工作流纯属多余）</li><li>模型加载加速 &amp; 显存优化。适配新一代模型</li><li>时序动画曲线、运镜权重渐变、视频帧调度</li></ol><p>本身有两百多个节点塞满菜单，新手打开会极度混乱；绝大多数功能半年内都用不到。</p><p><img src="'+q+'" alt="comfyui_2026-07-31_120442_284.png" loading="lazy"></p><p><span style="color:red;">注意：这几个节点包不用全部安装，根据需要选择安装即可。一起安装可能会有冲突，导致工作流运行异常。建议根据需要选择安装。</span></p><h3 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h3><p>在 ComfyUI 里，模型一般指真正参与运算的权重文件，例如 checkpoint、VAE、LoRA、ControlNet、放大模型等。</p><p>这些模型文件默认不会随ComfyUI安装而附带下载的。常见做法是从网上下载后放进 <strong>models</strong> 中的对应子文件夹，或按工作流/模板提示补全；</p><p>单个模型文件通常是数GB的大小，根据模型的复杂度和参数量而定。因此下载需要预留足够磁盘空间和网络时间。</p><h4 id="模型文件格式" tabindex="-1">模型文件格式 <a class="header-anchor" href="#模型文件格式" aria-label="Permalink to &quot;模型文件格式&quot;">​</a></h4><p>常见的模型文件格式：</p><ul><li><strong>.ckpt</strong>：传统格式，包含额外训练信息，体积较大。该文件包含模型的所有信息，包括权重、配置、训练记录等。</li><li><strong>.safetensors</strong>：推荐使用格式，体积小、加载快、安全。该文件仅包含模型的权重，不包含额外训练信息。</li></ul><p><span style="color:red;">注意：从模型网站下载的模型文件通常是 <code>.safetensors</code> 格式。因为不需要进行模型训练，所以推荐使用 <code>.safetensors</code> 格式。</span></p><h4 id="支持-不支持的模型" tabindex="-1">支持/不支持的模型 <a class="header-anchor" href="#支持-不支持的模型" aria-label="Permalink to &quot;支持/不支持的模型&quot;">​</a></h4><p>ComfyUI 官方支持的模型数量有限,但随着 ComfyUI 与开源社区的发展，支持会持续扩展。一旦某模型纳入支持，通常会在 <strong>模型模板库</strong> 中增加对应模板，便于一键使用。</p><p>另外并非所有模型都能开箱即用。 若你使用的是 ComfyUI 原生支持的模型，请先在 模板库 中确认是否已有匹配的模板与模型提示。</p><h4 id="在comfyui中如何使用模型" tabindex="-1">在comfyui中如何使用模型 <a class="header-anchor" href="#在comfyui中如何使用模型" aria-label="Permalink to &quot;在comfyui中如何使用模型&quot;">​</a></h4><ol><li><strong>将下载好的模型文件放到正确目录</strong>。 例如放入 <strong>models</strong> 目录下的某个子文件夹中。</li><li><strong>添加对应的加载器节点</strong>。根据模型文件的类型选择对应的加载器（checkpoint、LoRA、VAE 等）节点。</li><li><strong>在加载器节点中选择要使用的模型文件</strong>。</li><li><strong>把加载器节点连进工作流</strong>。若 ComfyUI 一直在运行，重启/刷新应用,以便列表更新。</li></ol><h2 id="可视化界面" tabindex="-1">可视化界面 <a class="header-anchor" href="#可视化界面" aria-label="Permalink to &quot;可视化界面&quot;">​</a></h2><p>ComfyUI 提供了一个可供用户操作和组织工作流的可视化界面，用于组织和调试工作流，并生成令人惊叹的作品。</p><p>如图是可视化界面 <img src="'+k+'" alt="comfyui_2026-07-13_151107_094.png" loading="lazy"></p><ul><li>① 主菜单：点击展开功能菜单，含文件操作、帮助菜单等。</li><li>② 左侧面板入口：显示各个功能面板。 <ul><li>ASSETS：显示生成的图像、视频等资产。</li><li>Nodes：列出 ComfyUI 原生及第三方节点。</li><li>Models：展示 ComfyUI 启动后检测到的模型信息，启动后若有模型下载等，按快捷键 r 刷新节点定义获取最新模型。</li><li>Workflows：展示本地保存的工作流。</li><li>Templates：提供 ComfyUI 内置工作流模板。</li></ul></li><li>③ 底部工具栏：包含一些常用的工具和选项等。</li><li>④ 顶部区域：显示当前已打开工作流的名称、状态、提示信息等。</li><li>⑤ 新建工作流按钮：点击新建空白工作流文件。</li><li>⑥ 右侧控制区：运行和队列控制管理，可运行工作流、查看队列。</li><li>⑦ 登录状态：默认不显示。</li><li>⑧ 快捷按钮：打开右侧面板。</li><li>⑨ 画布导航工具：可切换移动或平移模式，打开小地图、切换节点连线显示。</li></ul>',148)])])}const B=t(x,[["render",P]]);export{V as __pageData,B as default};
